#!/usr/bin/env python3
'''CPU-only, standalone semantic and invariant checks for K-SYS-005. No GPU, NCCL, files, subprocess, or network.'''

from math import isclose


def allreduce_sum(xs):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    n = len(xs[0])
    if any(len(row) != n for row in xs):
        raise ValueError('count mismatch')
    total = [sum(xs[s][i] for s in range(p)) for i in range(n)]
    return [list(total) for _ in range(p)]


def allgather(xs):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    n = len(xs[0])
    if any(len(row) != n for row in xs):
        raise ValueError('count mismatch')
    merged = [value for row in xs for value in row]
    return [list(merged) for _ in range(p)]


def reduce_scatter(xs, n):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    if any(len(row) != p * n for row in xs):
        raise ValueError('input count mismatch')
    total = [sum(xs[s][j] for s in range(p)) for j in range(p * n)]
    return [total[r * n:(r + 1) * n] for r in range(p)]


def broadcast(root, xs):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    if not (0 <= root < p):
        raise ValueError('root out of range')
    n = len(xs[0])
    if any(len(row) != n for row in xs):
        raise ValueError('count mismatch')
    return [list(xs[root]) for _ in range(p)]


def matching_error(traces):
    if len(traces) == 0:
        return 'no ranks'
    length = len(traces[0])
    for r, trace in enumerate(traces):
        if len(trace) != length:
            return 'length mismatch at rank ' + str(r)
    for i in range(length):
        first = traces[0][i]
        for r in range(1, len(traces)):
            if traces[r][i] != first:
                return 'ticket mismatch at slot ' + str(i)
    return None


def shape_only_check(traces):
    if len(traces) == 0:
        return 'no ranks'
    lengths = {len(t) for t in traces}
    if len(lengths) != 1:
        return 'length mismatch'
    for i in range(len(traces[0])):
        counts = {traces[r][i][1] for r in range(len(traces))}
        if len(counts) != 1:
            return 'count mismatch'
    return None


TRANSITIONS = {
    ('OPEN', 'close_success'): 'ISSUED',
    ('OPEN', 'close_progress'): 'ISSUE_PENDING',
    ('ISSUE_PENDING', 'poll_success'): 'ISSUED',
    ('ISSUE_PENDING', 'poll_fail'): 'FAILED',
    ('ISSUED', 'device_done'): 'DEVICE_DONE',
    ('DEVICE_DONE', 'consume'): 'CONSUMED',
}


def next_state(state, event):
    return TRANSITIONS.get((state, event), 'REJECT')


def failure_closure(events):
    failed = set()
    safe = set()
    for rank, event in events:
        if event == 'local_fail':
            failed.add(rank)
        elif event == 'abort':
            safe.add(rank)
        elif event == 'timeout':
            pass
        elif event == 'publish':
            if failed and rank not in failed:
                return 'publish after failure'
        elif event == 'finish':
            if failed and rank not in safe and rank not in failed:
                return 'finish without abort'
    if failed:
        for rank in failed:
            if rank not in safe:
                return 'failed rank not closed'
    return None


def ring_time(p, nbytes, alpha, beta):
    if p < 1 or nbytes < 0 or alpha < 0 or beta <= 0:
        raise ValueError('invalid cost input')
    if p == 1:
        return 0.0
    return 2 * (p - 1) * alpha + 2 * (p - 1) * nbytes / (p * beta)


def ring_time_by_steps(p, nbytes, alpha, beta):
    if p == 1:
        return 0.0
    total = 0.0
    for _ in range(2 * (p - 1)):
        total += alpha + (nbytes / p) / beta
    return total


def bad_ring_time(p, nbytes, alpha, beta):
    if p == 1:
        return 0.0
    return (p - 1) * alpha + (p - 1) * nbytes / (p * beta)


def buffer_main_bytes(kind, p, n, b):
    if kind == 'allreduce':
        return 2 * n * b
    if kind == 'allgather':
        return (p + 1) * n * b
    if kind == 'reducescatter':
        return (p + 1) * n * b
    if kind == 'reduce':
        return 2 * n * b
    if kind == 'broadcast':
        return n * b
    raise ValueError('unknown operation')


def check_semantics():
    p = 4
    n = 8
    xs = [[100 * r + i for i in range(n)] for r in range(p)]
    ar = allreduce_sum(xs)
    expected = [600 + 4 * i for i in range(n)]
    assert all(row == expected for row in ar)
    ag = allgather(xs)
    expected_ag = [100 * s + i for s in range(p) for i in range(n)]
    assert all(row == expected_ag for row in ag)
    wide = [[100 * r + j for j in range(p * n)] for r in range(p)]
    rs = reduce_scatter(wide, n)
    for r in range(p):
        expected_rs = [600 + 4 * j for j in range(r * n, (r + 1) * n)]
        assert rs[r] == expected_rs
    bc = broadcast(2, xs)
    assert all(row == xs[2] for row in bc)
    for one_p in (1, 2, 3):
        one = [[7 * r + i for i in range(5)] for r in range(one_p)]
        assert len(allreduce_sum(one)) == one_p
        assert allgather(one)[0] == [v for row in one for v in row]
        wide_one = [[100 * r + j for j in range(one_p * 5)] for r in range(one_p)]
        assert len(reduce_scatter(wide_one, 5)) == one_p
    empty = [[], [], []]
    assert allreduce_sum(empty) == [[], [], []]
    assert allgather(empty) == [[], [], []]
    assert reduce_scatter([[] for _ in range(3)], 0) == [[], [], []]
    assert broadcast(1, empty) == [[], [], []]
    print('semantics: p=4 n=8 allreduce[0][0]=' + str(ar[0][0]) + ' allreduce[3][7]=' + str(ar[3][7]))
    print('semantics: p=1 and zero-length edges accepted')


def check_identity():
    common = [('step7.layer0', 8, 'int32', 'allreduce', '-'), ('step7.layer1', 8, 'int32', 'allreduce', '-')]
    valid = [list(common) for _ in range(4)]
    assert matching_error(valid) is None
    bad_skip = [list(common) for _ in range(4)]
    bad_skip[0] = bad_skip[0][1:]
    assert matching_error(bad_skip) is not None
    bad_slot = [list(common) for _ in range(4)]
    bad_slot[0][0] = ('step8.layer0', 8, 'int32', 'allreduce', '-')
    assert matching_error(bad_slot) is not None
    assert shape_only_check(bad_slot) is None
    print('identity: skip rejected=' + str(matching_error(bad_skip) is not None) + ' slot mismatch rejected=' + str(matching_error(bad_slot) is not None))
    print('negative control: shape-only check accepted the same-count wrong-slot trace; identity check rejected it')


def check_completion_states():
    assert next_state('OPEN', 'close_progress') == 'ISSUE_PENDING'
    assert next_state('ISSUE_PENDING', 'consume') == 'REJECT'
    assert next_state('ISSUED', 'device_done') == 'DEVICE_DONE'
    assert next_state('DEVICE_DONE', 'consume') == 'CONSUMED'
    state = 'OPEN'
    for event in ('close_progress', 'poll_success', 'device_done', 'consume'):
        state = next_state(state, event)
        assert state != 'REJECT'
    assert state == 'CONSUMED'
    print('completion states: early consume rejected=' + str(next_state('ISSUE_PENDING', 'consume') == 'REJECT'))


def check_failure_closure():
    good = [(0, 'local_fail'), (0, 'abort'), (1, 'timeout'), (1, 'abort'), (2, 'abort'), (3, 'abort')]
    assert failure_closure(good) is None
    bad_finish = [(0, 'local_fail'), (1, 'finish')]
    assert failure_closure(bad_finish) is not None
    bad_publish = [(0, 'local_fail'), (1, 'publish')]
    assert failure_closure(bad_publish) is not None
    print('failure closure: survivor publish rejected=' + str(failure_closure(bad_publish) is not None))


def check_costs_and_capacity():
    alpha = 5e-6
    beta = 40 * 1024 ** 3
    for p in (1, 2, 4, 8):
        for nbytes in (0, 8192, 16 * 1024 * 1024):
            a = ring_time(p, nbytes, alpha, beta)
            b = ring_time_by_steps(p, nbytes, alpha, beta)
            assert isclose(a, b, rel_tol=1e-12, abs_tol=0.0)
    t = ring_time(4, 8192, alpha, beta)
    bad = bad_ring_time(4, 8192, alpha, beta)
    assert not isclose(t, bad, rel_tol=1e-12, abs_tol=0.0)
    b = 4
    n = 8
    assert buffer_main_bytes('allreduce', 4, n, b) == 64
    assert buffer_main_bytes('allgather', 4, n, b) == 160
    assert buffer_main_bytes('reducescatter', 4, n, b) == 160
    assert buffer_main_bytes('reduce', 4, n, b) == 64
    assert buffer_main_bytes('broadcast', 4, n, b) == 32
    print('cost: closed-form ring and step sum agree; p=4 nbytes=8192 time=' + str(t))
    print('negative control: omitted-factor ring formula was detected by the independent step-sum reference')


def main():
    check_semantics()
    check_identity()
    check_completion_states()
    check_failure_closure()
    check_costs_and_capacity()
    print('coverage: exact rank semantics, p=1 and empty inputs, logical identity, issue/device/consume states, failure closure, ideal ring cost, buffer formulas')
    print('not measured: any GPU, NCCL, network, or learner effect')


if __name__ == '__main__':
    main()
